const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Makes the release JS bundle rebuild when a committed .json file changes.
 *
 * `BundleHermesCTask` (the Gradle task that runs `expo export:embed` for
 * non-debuggable variants) declares its inputs as a file tree of `**./*.js`,
 * `.jsx`, `.ts` and `.tsx` only — see
 * node_modules/@react-native/gradle-plugin/.../tasks/BundleHermesCTask.kt.
 *
 * This app's data lives in `src/data/countryFacts.json`,
 * `countries.geo.json` and `labelPoints.json`, which Metro inlines into the
 * bundle. Editing one of them therefore does NOT invalidate the task: Gradle
 * marks it UP-TO-DATE and `assembleRelease` packages a stale bundle, silently,
 * with no warning. `npx expo run:android` hides this because Metro serves the
 * debug variant and watches every file.
 *
 * `sources` is a public `ConfigurableFileTree`, so we can widen it. `.expo/` is
 * excluded because it holds volatile generated JSON that would re-bundle for no
 * reason.
 *
 * **The same trap, one file type over: `assets/**.png`.** That task also runs the
 * `--assets-dest` pass that copies required images into `res/drawable-*`, so the
 * committed map-flag rasters (`assets/map-flags/`, written by
 * `scripts/build-flag-assets.mjs`) reach the APK through it too. Re-rendering them
 * at a different size or border colour touches no `.js`/`.ts`/`.json`, so without
 * this Gradle would mark the task UP-TO-DATE and ship the previous flags — the
 * identical silent-staleness bug this plugin was written for. Scoped to `assets/`
 * rather than a bare `**./*.png` so nothing in `node_modules` or `android/build`
 * drags the task along with it.
 *
 * This has to be a config plugin rather than a hand-edit: `android/` is
 * gitignored and regenerated by `expo prebuild`.
 */
const MARKER = '// [withJsonBundleInputs]';

const SNIPPET = `
${MARKER} .json and the assets/**.png|webp images are not inputs of BundleHermesCTask by
${MARKER} default, so editing src/data/*.json or re-rendering the flag images would leave
${MARKER} assembleRelease packaging a stale bundle and stale drawables.
tasks.withType(com.facebook.react.tasks.BundleHermesCTask).configureEach { bundleTask ->
    bundleTask.sources.include("**/*.json")
    bundleTask.sources.include("assets/**/*.png")
    bundleTask.sources.exclude("**/.expo/**/*")
}
`;

module.exports = function withJsonBundleInputs(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (!cfg.modResults.contents.includes(MARKER)) {
      cfg.modResults.contents += SNIPPET;
    }
    return cfg;
  });
};
